import re

def slugify(s):
    s = s.strip().lower()
    s = re.sub(r'[^\w\s-]', '', s)
    s = re.sub(r'[\s_-]+', '-', s)
    return s.strip('-')

import re

def slugify(s):
    return re.sub(r'[^a-z0-9]+', '-', s.lower()).strip('-')

import re

def slugify(s):
    s = s.replace(',', '').replace('!', '')
    return re.sub(r'\s+', '-', s.strip().lower())

import re

_PUNCT = re.compile(r'[,.!?]')

def slugify(s):
    s = _PUNCT.sub('', s)
    return re.sub(r'\s+', '-', s.strip().lower())
